pub fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Only need to check parent nodes: indices 0 through floor(n/2)-1
    for i in 0..n / 2 {
        let left = 2 * i + 1;
        if a[i] > a[left] {
            return false;
        }
        let right = 2 * i + 2;
        if right < n && a[i] > a[right] {
            return false;
        }
    }
    true
}

